private function sessions(array$ids):array{$sql='SELECT s.term_session_id,s.term_id,s.classroom_id,s.session_type,s.makeup_for_session_id,s.cancellation_status,s.cancellation_requested_by,s.cancellation_decided_by,b.status booking_status,b.requested_date date,b.start_time,b.end_time,b.timezone_id FROM academy_branch_course_term_sessions s JOIN academy_branch_bookings b ON b.booking_id=s.booking_id WHERE s.deleted_at IS NULL AND b.deleted_at IS NULL AND s.term_id IN ('.implode(',',array_map('intval',$ids)).') ORDER BY b.requested_date,b.start_time,s.term_session_id';$rows=db()->query($sql)->fetchAll();$sessionIds=array_map(fn($r)=>(int)$r['term_session_id'],$rows);$reasons=[];if($sessionIds)foreach(DB::table('translations')->where('table_name','academy_branch_course_term_sessions')->where('field','cancellation_reason')->where('locale','fa')->whereIn('table_id',$sessionIds)->whereNull('deleted_at')->get()as$t)$reasons[(int)$t['table_id']]=$t['value'];$out=[];$regularNumbers=[];$byId=[];foreach($rows as$r){$byId[(int)$r['term_session_id']]=$r;if(($r['session_type']??'regular')==='regular')$regularNumbers[(int)$r['term_id']][(int)$r['term_session_id']]=count($regularNumbers[(int)$r['term_id']]??[])+1;}$root=function(int$id)use(&$root,$byId):int{$seen=[];while(isset($byId[$id])&&($byId[$id]['session_type']??'regular')==='makeup'&&!isset($seen[$id])){$seen[$id]=true;$id=(int)($byId[$id]['makeup_for_session_id']??0);}return$id;};foreach($rows as$r){$id=(int)$r['term_session_id'];$termId=(int)$r['term_id'];$parent=(int)($r['makeup_for_session_id']??0);$type=(string)($r['session_type']??'regular');$number=$regularNumbers[$termId][$root($id)]??0;$out[$termId][]=['id'=>$id,'number'=>$number,'type'=>$type,'makeupForSessionId'=>$parent?:null,'date'=>$r['date'],'startTime'=>substr((string)$r['start_time'],0,5),'endTime'=>substr((string)$r['end_time'],0,5),'timezoneId'=>(int)($r['timezone_id']??0),'classroomId'=>(int)$r['classroom_id'],'bookingStatus'=>(string)$r['booking_status']